} else if (key === "Escape") {
  // Hitting Escape:
  // - Closes submenu.
  // - Moves focus to parent menubar item.
  preventEvent(event);
  // Close the current submenu by closing its toggle (which is in the parent menu item)
  const parentMenuItem = this.elements.parentMenu.currentMenuItem;
  if (parentMenuItem && parentMenuItem.elements.toggle) {
    parentMenuItem.elements.toggle.close();
  }
  // Then focus the parent menu item (the Facts item)
  this.elements.parentMenu.focusCurrentChild();
}
